use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let text = input.as_str().unwrap();
    let shift = input.as_i64().unwrap();
    let mut result = String::new();
    for c in text.chars() {
        if c.is_lowercase() {
            let ascii = c as u8;
            let new_ascii = (ascii as u8 + shift) % 26;
            result.push((new_ascii as char).to_string());
        } else {
            result.push(c);
        }
    }
    Value::String(result)
}
